(window.__quranSurahs=window.__quranSurahs||{})[106]={"nomPhon":"Quraish","versets":{"1":{"text":"A cause du pacte des Coraïch,","arabe":"لِإِيلَٰفِ قُرَيْشٍ"},"2":{"text":"De leur pacte [concernant] les voyages d'hiver et d'été.","arabe":"إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ"},"3":{"text":"Qu'ils adorent donc le Seigneur de cette Maison [la Ka'ba],","arabe":"فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ"},"4":{"text":"qui les a nourris contre la faim et rassurés de la crainte!","arabe":"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ"}}};